import {SKILL_CLASSES} from './expedition-skill-classes.mjs';
import {equipmentClassRank} from './expedition-equipment.mjs';
import {equipmentTotals}from'./expedition-equipment.mjs';import{HEROES,SKILLS,DEFENSES}from'./expedition-data.mjs';
export function equipmentRankRows(h){const t=HEROES.find(v=>v.id===h?.id);if(!t)return [];const totals=equipmentTotals(h.gear),keys=[...new Set([...Object.keys(totals.ranks||{}),...Object.keys(totals.classRanks||{}).flatMap(id=>SKILL_CLASSES[id].members)])];return keys.map(key=>{const direct=totals.ranks?.[key]||0,classes=equipmentClassRank(h.gear,key),equipment=direct+classes;const[kind,id]=key.split(':'),available=kind==='skill'?t.skills.includes(id):Boolean(DEFENSES[id]&&id!=='natural'),name=(kind==='skill'?SKILLS[id]:DEFENSES[id]).name,base=kind==='skill'?t.base:6,specialization=(kind==='skill'?h.trained:h.defenseFocus)===id?3:0,training=h.training?.[key]||0;return {key,kind,id,name,available,base,specialization,training,equipment,...(classes?{classEquipment:classes,directEquipment:direct}:{}),total:available?base+specialization+training+equipment:0};});}
export function equipmentRanksView(h){const rows=equipmentRankRows(h);return rows.length?`<section class="equipment-ranks"><h3>装备技能等级 · 当前静态来源</h3>${rows.map(r=>`<article data-equipment-rank="${r.key}"><b>${r.name}</b>${r.available?`<p>基础 ${r.base} + 专修 ${r.specialization} + 永久培养 ${r.training} + 装备 ${r.equipment} = <strong data-equipment-rank-total="${r.key}">${r.total}</strong>${r.classEquipment?'（其中类别 +'+r.classEquipment+'，单技能 +'+r.directEquipment+'；已计入装备合计）':''}</p>`:'<p>本职业未掌握，此项等级加成未生效；装备不会授予技能。</p>'}</article>`).join('')}<p>仅当前穿戴生效，不计库存或未应用配装；装备等级不算永久培养、经验投入或课程解锁，换下即时移除。数值为出发前静态等级，临时效果和本次防御回退另见当次战报；固定效果不保证随等级改变，技能费用沿原规则。</p></section>`:'';}
